class Solution:
    def maximumWhiteTiles(self, tiles: list[list[int]], carpetLen: int) -> int:
        best = 0
        for start, _ in tiles:
            end = start + carpetLen - 1
            covered = 0
            for a, b in tiles:
                overlap = min(b, end) - max(a, start) + 1
                if overlap > 0:
                    covered += overlap
            best = max(best, covered)
        return best

